// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface INutboxRouter {
    enum SourceType {
        V2_PAIR,
        V3_POOL,
        UNISWAP_V4,
        PANCAKE_V4_CL
    }

    struct UniswapV4Source {
        address poolManager;
        address currency0;
        address currency1;
        uint24 fee;
        int24 tickSpacing;
        address hooks;
    }

    struct PancakeV4CLSource {
        address currency0;
        address currency1;
        address hooks;
        address poolManager;
        uint24 fee;
        bytes32 parameters;
    }

    /// @dev Constructor-only bootstrap entry. Runtime administration continues to use addPricePool().
    struct InitialPricePool {
        address token0;
        address token1;
        SourceType sourceType;
        bytes sourceData;
    }

    /// @dev Constructor-only bootstrap entry. Pool IDs must reference entries initialized first.
    struct InitialRoute {
        address tokenIn;
